    "username" varchar(256) DEFAULT NULL,
    "password" varchar(512) DEFAULT NULL,
    "real_name" varchar(256) DEFAULT NULL,
    "phone" varchar(128) DEFAULT NULL,
    "mail" varchar(512) DEFAULT NULL,
    "deletion_time" bigint DEFAULT NULL,
    "create_time" timestamp without time zone DEFAULT NULL,
    "update_time" timestamp without time zone DEFAULT NULL,
    "del_flag" smallint DEFAULT NULL,
    PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX t_user_idx_unique_username ON t_user ("username");

CREATE TABLE t_api_token (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "username" varchar(64) NOT NULL,
    "token_hash" char(64) NOT NULL,
    "token_last4" varchar(8) NOT NULL,
    "name" varchar(128) NOT NULL DEFAULT '',
    "enable_status" smallint NOT NULL DEFAULT 0,
    "valid_date" timestamp without time zone DEFAULT NULL,
    "describe" varchar(255) DEFAULT NULL,
    "create_time" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "update_time" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "del_flag" smallint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX t_api_token_uk_token_hash ON t_api_token ("token_hash");

CREATE INDEX t_api_token_idx_username ON t_api_token ("username");

CREATE TABLE t_link_first_visit (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY,
